CREATE TABLE supplier (tenant_id uuid NOT NULL,company_id uuid NOT NULL,id uuid NOT NULL,code text NOT NULL,name text NOT NULL,phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 0,PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,code),FOREIGN KEY(tenant_id,company_id) REFERENCES company(tenant_id,id));
CREATE TABLE purchase_order (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,supplier_id uuid NOT NULL,warehouse_id uuid NOT NULL,created_by uuid NOT NULL,approved_by uuid,business_date date NOT NULL,status text NOT NULL CHECK(status IN ('DRAFT','IN_REVIEW','APPROVED','PARTIALLY_RECEIVED','RECEIVED')),version bigint NOT NULL DEFAULT 0,total_xaf bigint NOT NULL CHECK(total_xaf>0),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,supplier_id) REFERENCES supplier(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,branch_id,warehouse_id) REFERENCES warehouse(tenant_id,company_id,branch_id,id));
CREATE TABLE purchase_line (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,purchase_id uuid NOT NULL,product_id uuid NOT NULL,quantity_milli bigint NOT NULL CHECK(quantity_milli>0),received_milli bigint NOT NULL DEFAULT 0 CHECK(received_milli>=0 AND received_milli<=quantity_milli),unit_price_xaf bigint NOT NULL CHECK(unit_price_xaf>0),total_xaf bigint NOT NULL CHECK(total_xaf>0),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,purchase_id,product_id),FOREIGN KEY(tenant_id,company_id,branch_id,purchase_id) REFERENCES purchase_order(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,product_id) REFERENCES catalog_product(tenant_id,company_id,id));
CREATE TABLE purchase_receipt (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,purchase_id uuid NOT NULL,operation_id uuid NOT NULL,actor_id uuid NOT NULL,business_date date NOT NULL,total_xaf bigint NOT NULL CHECK(total_xaf>0),reason text NOT NULL CHECK(length(trim(reason))>0),created_transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,operation_id),UNIQUE(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,branch_id,purchase_id) REFERENCES purchase_order(tenant_id,company_id,branch_id,id));
CREATE TABLE purchase_receipt_line (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,receipt_id uuid NOT NULL,purchase_line_id uuid NOT NULL,product_id uuid NOT NULL,quantity_milli bigint NOT NULL CHECK(quantity_milli>0),value_xaf bigint NOT NULL CHECK(value_xaf>0),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,receipt_id,purchase_line_id),FOREIGN KEY(tenant_id,company_id,branch_id,receipt_id) REFERENCES purchase_receipt(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,purchase_line_id) REFERENCES purchase_line(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,product_id) REFERENCES catalog_product(tenant_id,company_id,id));
CREATE TABLE supplier_invoice (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,receipt_id uuid NOT NULL,supplier_id uuid NOT NULL,operation_id uuid NOT NULL,actor_id uuid NOT NULL,business_date date NOT NULL,total_xaf bigint NOT NULL CHECK(total_xaf>0),supplier_reference text NOT NULL CHECK(length(trim(supplier_reference))>0),reason text NOT NULL CHECK(length(trim(reason))>0),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,receipt_id),UNIQUE(tenant_id,company_id,supplier_id,supplier_reference),UNIQUE(tenant_id,operation_id),FOREIGN KEY(tenant_id,company_id,branch_id,receipt_id) REFERENCES purchase_receipt(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,supplier_id) REFERENCES supplier(tenant_id,company_id,id));
DO $$ DECLARE t text;predicate text;BEGIN FOREACH t IN ARRAY ARRAY['supplier','purchase_order','purchase_line','purchase_receipt','purchase_receipt_line','supplier_invoice'] LOOP predicate:='tenant_id=app_tenant() AND company_id=app_company()';IF t<>'supplier' THEN predicate:=predicate||' AND branch_id=app_branch()';END IF;EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING (%s) WITH CHECK (%s)',t,predicate,predicate);END LOOP;END $$;
GRANT SELECT,INSERT ON supplier,purchase_order,purchase_line,purchase_receipt,purchase_receipt_line,supplier_invoice TO quincai_app;
GRANT UPDATE ON purchase_order,purchase_line TO quincai_app;
GRANT UPDATE(version) ON supplier TO quincai_app;
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['purchase_receipt','purchase_receipt_line','supplier_invoice'] LOOP EXECUTE format('CREATE TRIGGER immutable_fact BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation()',t);END LOOP;END $$;
CREATE FUNCTION protect_purchase_order() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF OLD.status='RECEIVED' THEN RAISE EXCEPTION 'Received order immutable' USING ERRCODE='23514';END IF;
 IF (NEW.supplier_id,NEW.warehouse_id,NEW.business_date,NEW.total_xaf,NEW.created_by,NEW.tenant_id,NEW.company_id,NEW.branch_id) IS DISTINCT FROM (OLD.supplier_id,OLD.warehouse_id,OLD.business_date,OLD.total_xaf,OLD.created_by,OLD.tenant_id,OLD.company_id,OLD.branch_id) THEN RAISE EXCEPTION 'Order content immutable; create replacement draft' USING ERRCODE='23514';END IF;
 RETURN NEW;END $$;
CREATE TRIGGER purchase_order_guard BEFORE UPDATE ON purchase_order FOR EACH ROW EXECUTE FUNCTION protect_purchase_order();
CREATE FUNCTION protect_purchase_line() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN
 IF (NEW.purchase_id,NEW.product_id,NEW.quantity_milli,NEW.unit_price_xaf,NEW.total_xaf,NEW.tenant_id,NEW.company_id,NEW.branch_id) IS DISTINCT FROM (OLD.purchase_id,OLD.product_id,OLD.quantity_milli,OLD.unit_price_xaf,OLD.total_xaf,OLD.tenant_id,OLD.company_id,OLD.branch_id) OR NEW.received_milli<OLD.received_milli THEN RAISE EXCEPTION 'Order quantities and valuation immutable; receipts append progress' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER purchase_line_guard BEFORE UPDATE ON purchase_line FOR EACH ROW EXECUTE FUNCTION protect_purchase_line();
CREATE FUNCTION seal_purchase_receipt_lines() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE origin xid8;BEGIN SELECT created_transaction_id INTO origin FROM purchase_receipt WHERE tenant_id=NEW.tenant_id AND company_id=NEW.company_id AND id=NEW.receipt_id;IF origin IS NULL OR origin<>pg_current_xact_id() THEN RAISE EXCEPTION 'Receipt lines must be inserted with receipt' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER purchase_receipt_line_seal BEFORE INSERT ON purchase_receipt_line FOR EACH ROW EXECUTE FUNCTION seal_purchase_receipt_lines();
CREATE TABLE purchase_supplier_return (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,receipt_id uuid NOT NULL,operation_id uuid NOT NULL,actor_id uuid NOT NULL,business_date date NOT NULL,total_xaf bigint NOT NULL CHECK(total_xaf>0),reason text NOT NULL CHECK(length(trim(reason))>0),created_transaction_id xid8 NOT NULL DEFAULT pg_current_xact_id(),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,operation_id),UNIQUE(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,branch_id,receipt_id) REFERENCES purchase_receipt(tenant_id,company_id,branch_id,id));
CREATE TABLE purchase_supplier_return_line (tenant_id uuid NOT NULL,company_id uuid NOT NULL,branch_id uuid NOT NULL,id uuid NOT NULL,return_id uuid NOT NULL,receipt_line_id uuid NOT NULL,product_id uuid NOT NULL,quantity_milli bigint NOT NULL CHECK(quantity_milli>0),value_xaf bigint NOT NULL CHECK(value_xaf>0),PRIMARY KEY(tenant_id,company_id,id),UNIQUE(tenant_id,company_id,return_id,receipt_line_id),FOREIGN KEY(tenant_id,company_id,branch_id,return_id) REFERENCES purchase_supplier_return(tenant_id,company_id,branch_id,id),FOREIGN KEY(tenant_id,company_id,receipt_line_id) REFERENCES purchase_receipt_line(tenant_id,company_id,id),FOREIGN KEY(tenant_id,company_id,product_id) REFERENCES catalog_product(tenant_id,company_id,id));
DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['purchase_supplier_return','purchase_supplier_return_line'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY scope_isolation ON %I USING (tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch()) WITH CHECK (tenant_id=app_tenant() AND company_id=app_company() AND branch_id=app_branch())',t);EXECUTE format('CREATE TRIGGER immutable_fact BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION reject_fact_mutation()',t);END LOOP;END $$;
GRANT SELECT,INSERT ON purchase_supplier_return,purchase_supplier_return_line TO quincai_app;
CREATE FUNCTION seal_purchase_supplier_return_lines() RETURNS trigger LANGUAGE plpgsql AS $$ DECLARE origin xid8;BEGIN SELECT created_transaction_id INTO origin FROM purchase_supplier_return WHERE tenant_id=NEW.tenant_id AND company_id=NEW.company_id AND id=NEW.return_id;IF origin IS NULL OR origin<>pg_current_xact_id() THEN RAISE EXCEPTION 'Return lines must be inserted with return' USING ERRCODE='23514';END IF;RETURN NEW;END $$;
CREATE TRIGGER purchase_supplier_return_line_seal BEFORE INSERT ON purchase_supplier_return_line FOR EACH ROW EXECUTE FUNCTION seal_purchase_supplier_return_lines();
